arguments.command:
cd /workspace && mkdir -p tmp && python3 -I submission/main.py < examples/diamond.json > tmp/out.json; echo "exit=$?"; python3 - <<'EOF'
import json
a=json.load(open('/workspace/tmp/out.json'))
b=json.load(open('/workspace/examples/diamond.expected.json'))
def cmp(x,y,path=""):
    if type(x)!=type(y): print("TYPE",path,type(x),type(y)); return
    if isinstance(x,dict):
        if set(x)!=set(y): print("KEYS",path,set(x)^set(y)); return
        for k in x: cmp(x[k],y[k],path+"/"+str(k))
    elif isinstance(x,list):
        if len(x)!=len(y): print("LEN",path,len(x),len(y)); return
        for i,(p,q) in enumerate(zip(x,y)): cmp(p,q,path+f"[{i}]")
    else:
        if x!=y: print("VAL",path,repr(x),repr(y))
cmp(a,b)
print("MATCH-CHECK-DONE")
EOF
